import os
import sqlite3
from flask import Flask, request, jsonify, g

app = Flask(__name__)
DATABASE = '/var/lib/app/users.db'

def get_db():
    db = getattr(g, '_database', None)
    if db is None:
        db = g._database = sqlite3.connect(DATABASE)
        db.row_factory = sqlite3.Row
    return db

@app.teardown_appcontext
def close_connection(exception):
    db = getattr(g, '_database', None)
    if db is not None:
        db.close()

def init_db():
    with app.app_context():
        db = get_db()
        db.execute('''CREATE TABLE IF NOT EXISTS users (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            username TEXT UNIQUE NOT NULL,
            email TEXT NOT NULL,
            role TEXT DEFAULT 'user',
            department TEXT,
            active INTEGER DEFAULT 1
        )''')
        db.execute('''CREATE TABLE IF NOT EXISTS audit_log (
            id INTEGER PRIMARY KEY AUTOINCREMENT,
            action TEXT,
            target_user TEXT,
            performed_by TEXT,
            timestamp DATETIME DEFAULT CURRENT_TIMESTAMP
        )''')
        db.commit()

@app.route('/api/users/search', methods=['GET'])
def search_users():
    """Search users by department and role for directory listing."""
    department = request.args.get('department', '')
    role = request.args.get('role', '')
    include_inactive = request.args.get('include_inactive', '0')

    # Build query with filters
    base_query = "SELECT id, username, email, role, department FROM users WHERE 1=1"

    if department:
        base_query += f" AND department = '{department}'"
    if role:
        base_query += f" AND role = '{role}'"
    if include_inactive != '1':
        base_query += " AND active = 1"

    try:
        db = get_db()
        cursor = db.execute(base_query)
        results = [dict(row) for row in cursor.fetchall()]
        return jsonify({'users': results, 'count': len(results)})
    except Exception as e:
        app.logger.error(f"Search error: {str(e)}")
        return jsonify({'error': 'Search failed'}), 500

@app.route('/api/users/<int:user_id>', methods=['GET'])
def get_user(user_id):
    """Get user details by ID."""
    db = get_db()
    cursor = db.execute(
        "SELECT id, username, email, role, department FROM users WHERE id = ?",
        (user_id,)
    )
    user = cursor.fetchone()
    if user:
        return jsonify(dict(user))
    return jsonify({'error': 'User not found'}), 404

@app.route('/api/users', methods=['POST'])
def create_user():
    """Create a new user (admin only - enforced by upstream auth)."""
    data = request.get_json()
    if not data or 'username' not in data or 'email' not in data:
        return jsonify({'error': 'Missing required fields'}), 400

    db = get_db()
    try:
        db.execute(
            "INSERT INTO users (username, email, role, department) VALUES (?, ?, ?, ?)",
            (data['username'], data['email'], data.get('role', 'user'), data.get('department', ''))
        )
        db.commit()
        # Log the action
        performer = request.headers.get('X-Authenticated-User', 'unknown')
        db.execute(
            "INSERT INTO audit_log (action, target_user, performed_by) VALUES (?, ?, ?)",
            ('CREATE_USER', data['username'], performer)
        )
        db.commit()
        return jsonify({'message': 'User created'}), 201
    except sqlite3.IntegrityError:
        return jsonify({'error': 'Username already exists'}), 409

@app.route('/api/health', methods=['GET'])
def health_check():
    return jsonify({'status': 'healthy', 'version': '2.4.1'})

if __name__ == '__main__':
    init_db()
    app.run(host='0.0.0.0', port=8080)
